541	  constructor(graph: Graph, pointers: Pointers) {
542	    super();
543	    this._graph = graph;
544	    this._pointers = pointers;
545	    return new Proxy(this, {
546	      apply: (target, _, args: [string]) => {
547	        const _call = target._call.bind(target);
548	        return _call(...args);
549	      },
550	    });
551	  }
552	
553	  _call(input: string) {
554	    return this.add(input);
555	  }
556	
557	  __call__(input: string): ParseState {
558	    return this.add(input);
559	  }
560	
561	  *[Symbol.iterator](): IterableIterator<ResolvedRule> {
562	    yield* this.rules();
563	  }
564	
565	  *rules(): IterableIterator<ResolvedRule> {
566	    const rules = new Set<string>();
567	    for (const { rule, } of this._pointers) {
568	      const key = JSON.stringify(rule);
569	      if (!rules.has(key)) {
570	        rules.add(key);
571	        yield rule;
572	      }
573	    }
574	  }
575	
576	  add(input: string): ParseState {
577	    const pointers = this._graph.add(input, this._pointers);
578	    return new ParseState(this._graph, pointers);
579	  }
580	
581	  get size() {
582	    return Array.from(this.rules()).length;
583	  }
584	
585	  get grammar() {
586	    return this._graph.grammar;
587	  }
