785	function makeCharRule<R extends (InternalRuleDefChar | InternalRuleDefCharNot)>(ruleDef: R): R extends InternalRuleDefChar ? RuleChar : RuleCharExclude {
786	  return {
787	    type: isRuleDefCharNot(ruleDef) ? RuleType.CHAR_EXCLUDE : RuleType.CHAR,
788	    value: [...ruleDef.value,],
789	  } as R extends InternalRuleDefChar ? RuleChar : RuleCharExclude;
790	}
