792	export const buildRuleStack = (linearRules: InternalRuleDef[]): UnresolvedRule[][] => {
793	  let paths: UnresolvedRule[] = [];
794	
795	  const stack: UnresolvedRule[][] = [];
796	
797	  let idx = 0;
798	  while (idx < linearRules.length) {
799	    const ruleDef = linearRules[idx];
800	    if (isRuleDefChar(ruleDef) || isRuleDefCharNot(ruleDef)) {
801	      // this could be a single char, or a range, or a sequence of alts; we don't know until we step through it.
802	      const charRule = makeCharRule(ruleDef);
803	      idx += 1;
804	      let rule = linearRules[idx];
805	      while (idx < linearRules.length && (isRuleDefCharRngUpper(rule) || isRuleDefCharAlt(rule))) {
806	        if (isRuleDefCharRngUpper(rule)) {
807	          // previous rule value should be a number
808	          const prevValue = charRule.value.pop();
809	          if (isRange(prevValue)) {
810	            throw new Error(`Unexpected range, expected a number but got an array: ${JSON.stringify(prevValue)}`);
811	          }
812	          if (prevValue === undefined) {
813	            throw new Error('Unexpected undefined value');
814	          }
815	          charRule.value.push([
816	            prevValue,
817	            rule.value,
818	          ]);
819	        }
820	        if (isRuleDefCharAlt(rule)) {
821	          charRule.value.push(rule.value);
822	        }
823	        idx += 1;
824	        rule = linearRules[idx];
825	      }
826	      paths.push(charRule);
827	    } else {
828	      if (isRuleDefAlt(ruleDef)) {
829	        if (!paths.length) {
830	          throw new Error('Encountered alt without anything before it');
831	        }
832	        paths.push({ type: RuleType.END, });
833	        stack.push(paths);
834	        paths = [];
835	      } else if (isRuleDefEnd(ruleDef)) {
836	        paths.push({
837	          type: RuleType.END,
838	        });
839	      } else if (isRuleDefRef(ruleDef)) {
840	        paths.push(new RuleRef(ruleDef.value));
841	      } else if (isRuleDefCharAlt(ruleDef)) {
842	        throw new Error(`Encountered char alt, should be handled by above block: ${ruleDef.type}`);
843	      } else {
844	        throw new Error(`Unsupported rule type: ${ruleDef.type}`);
845	      }
846	      idx += 1;
847	    }
848	
849	  }
850	  if (!isRuleEnd(paths[paths.length - 1])) {
851	    paths.push({ type: RuleType.END, });
852	  }
853	
854	  stack.push(paths);
855	
856	  return stack;
857	};
