                    f"{previous_as_string}{get_input_as_string(most_recent_input)}",
                    pos + len(previous_as_string),
                ),
            ]
        )
        super().__init__(message)
        self.name = "InputParseError"
        self.message = message

    def __str__(self) -> str:
