    def add(self, src: ValidInput, pointers: Optional[GenericSet] = None) -> GenericSet:
        pointers = pointers if pointers is not None else self._get_initial_pointers()
        code_points = get_input_as_code_points(src)
        for code_point_pos, code_point in enumerate(code_points):
