    def print(self, pointers=None, colors: bool = False) -> str:
        col = colorize if colors else no_colorize
        graph_view = []
        for nodes in self.roots.values():
            for node in nodes.values():
                graph_view.append(
                    node.print(pointers=pointers, show_position=True, colorize=col)
                )
        joined = "\n".join(graph_view)
        return f"\n{joined}"

    def __repr__(self) -> str:
        return self.print(colors=True)

    @staticmethod
    def _iterate_over_pointers(pointers: GenericSet):
        # Keyed by rule identity, as in the reference implementation: identical rules
        # share a single reference thanks to the unique-rule set built in __init__.
